69	    // ---------- 主流程：登记 → 读数 → DUE → 保养 → OK → 历史 ----------
70	
71	    @Test
72	    void mainFlow_statusTransitionsAndHistory() throws Exception {
73	        register("eq-main", 100);
74	
75	        // 初始状态：累计工时 0，OK
76	        mockMvc.perform(get("/api/equipment/eq-main/status"))
77	                .andExpect(status().isOk())
78	                .andExpect(jsonPath("$.version").value(1))
79	                .andExpect(jsonPath("$.latestCumulativeMinutes").value(0))
80	                .andExpect(jsonPath("$.runMinutes").value(0))
81	                .andExpect(jsonPath("$.status").value("OK"));
82	
83	        addReading("eq-main", "add-r1", 1, "r1", "2026-01-01T10:00:00Z", 50, 201);
84	        mockMvc.perform(get("/api/equipment/eq-main/status"))
85	                .andExpect(jsonPath("$.runMinutes").value(50))
86	                .andExpect(jsonPath("$.status").value("OK"));
87	
88	        // 达到保养周期 → DUE
89	        addReading("eq-main", "add-r2", 2, "r2", "2026-01-01T11:00:00Z", 130, 201);
90	        mockMvc.perform(get("/api/equipment/eq-main/status"))
91	                .andExpect(jsonPath("$.runMinutes").value(130))
92	                .andExpect(jsonPath("$.status").value("DUE"));
93	
94	        // 完成保养：锚点 r2 修订号 1
95	        mockMvc.perform(post("/api/equipment/eq-main/maintenances")
96	                        .contentType(MediaType.APPLICATION_JSON)
97	                        .content("""
98	                                {"requestId":"mnt-1","expectedVersion":3,"readingId":"r2","anchorRevisionNo":1}
99	                                """))
100	                .andExpect(status().isCreated())
101	                .andExpect(jsonPath("$.anchorSampledAt").value("2026-01-01T11:00:00Z"))
102	                .andExpect(jsonPath("$.anchorCumulativeMinutes").value(130))
103	                .andExpect(jsonPath("$.equipmentVersion").value(4));
104	
105	        // 保养后本轮运行分钟从锚点重算
106	        mockMvc.perform(get("/api/equipment/eq-main/status"))
107	                .andExpect(jsonPath("$.version").value(4))
108	                .andExpect(jsonPath("$.lastMaintenanceAnchorCumulativeMinutes").value(130))
109	                .andExpect(jsonPath("$.runMinutes").value(0))
110	                .andExpect(jsonPath("$.status").value("OK"));
111	
112	        addReading("eq-main", "add-r3", 4, "r3", "2026-01-01T12:00:00Z", 180, 201);
113	        mockMvc.perform(get("/api/equipment/eq-main/status"))
114	                .andExpect(jsonPath("$.runMinutes").value(50))
115	                .andExpect(jsonPath("$.status").value("OK"));
116	
117	        // 读数历史：按采样时刻升序，r2 已锚定
118	        mockMvc.perform(get("/api/equipment/eq-main/readings"))
119	                .andExpect(status().isOk())
120	                .andExpect(jsonPath("$", hasSize(3)))
121	                .andExpect(jsonPath("$[0].readingId").value("r1"))
122	                .andExpect(jsonPath("$[1].readingId").value("r2"))
123	                .andExpect(jsonPath("$[1].anchored").value(true))
124	                .andExpect(jsonPath("$[2].readingId").value("r3"));
125	
126	        // 保养历史：锚点快照保留
127	        mockMvc.perform(get("/api/equipment/eq-main/maintenances"))
128	                .andExpect(status().isOk())
129	                .andExpect(jsonPath("$", hasSize(1)))
130	                .andExpect(jsonPath("$[0].readingId").value("r2"))
131	                .andExpect(jsonPath("$[0].anchorRevisionNo").value(1))
132	                .andExpect(jsonPath("$[0].anchorCumulativeMinutes").value(130));
133	
134	        // 修订历史：初始登记为修订 1
135	        mockMvc.perform(get("/api/equipment/eq-main/readings/r2/revisions"))
136	                .andExpect(status().isOk())
137	                .andExpect(jsonPath("$", hasSize(1)))
138	                .andExpect(jsonPath("$[0].revisionNo").value(1))
139	                .andExpect(jsonPath("$[0].cumulativeMinutes").value(130));
140	    }
