195	    // ---------- 单调性与补录 ----------
196	
197	    @Test
198	    void addReading_backfillMustSatisfyBothNeighbors() throws Exception {
199	        register("eq-mono", 1000);
200	        addReading("eq-mono", "m1", 1, "r1", "2026-01-01T10:00:00Z", 100, 201);
201	        addReading("eq-mono", "m2", 2, "r3", "2026-01-01T12:00:00Z", 300, 201);
202	
203	        // 合法补录：100 <= 200 <= 300
204	        addReading("eq-mono", "m3", 3, "r2", "2026-01-01T11:00:00Z", 200, 201);
205	
206	        // 补录超过后邻（300）：即使不小于前邻也必须 422，不得仅与最新值比较
207	        addReading("eq-mono", "m4", 4, "r2x", "2026-01-01T11:30:00Z", 350, 422);
208	        // 补录低于前邻（100）
209	        addReading("eq-mono", "m5", 4, "r2y", "2026-01-01T10:30:00Z", 50, 422);
210	        // 末尾追加低于最新值
211	        addReading("eq-mono", "m6", 4, "r4", "2026-01-01T13:00:00Z", 250, 422);
212	        // 边界相等允许（单调不减）
213	        addReading("eq-mono", "m7", 4, "r4", "2026-01-01T13:00:00Z", 300, 201);
214	
215	        // 失败分支均未落库：共 4 条读数
216	        mockMvc.perform(get("/api/equipment/eq-mono/readings"))
217	                .andExpect(jsonPath("$", hasSize(4)));
218	    }
