276	    @Test
277	    void maintenance_anchorRules() throws Exception {
278	        register("eq-mnt", 1000);
279	        addReading("eq-mnt", "a1", 1, "r1", "2026-01-01T10:00:00Z", 100, 201);
280	        addReading("eq-mnt", "a2", 2, "r2", "2026-01-01T11:00:00Z", 200, 201);
281	
282	        // 锚点读数不存在 → 404
283	        mockMvc.perform(post("/api/equipment/eq-mnt/maintenances")
284	                        .contentType(MediaType.APPLICATION_JSON)
285	                        .content("""
286	                                {"requestId":"mn-x","expectedVersion":3,"readingId":"nope","anchorRevisionNo":1}
287	                                """))
288	                .andExpect(status().isNotFound());
289	
290	        // 锚点修订号与当前修订号不一致 → 409
291	        mockMvc.perform(post("/api/equipment/eq-mnt/maintenances")
292	                        .contentType(MediaType.APPLICATION_JSON)
293	                        .content("""
294	                                {"requestId":"mn-x2","expectedVersion":3,"readingId":"r1","anchorRevisionNo":7}
295	                                """))
296	                .andExpect(status().isConflict())
297	                .andExpect(jsonPath("$.code").value("ANCHOR_REVISION_CONFLICT"));
298	
299	        // 第一次保养可选任意读数
300	        mockMvc.perform(post("/api/equipment/eq-mnt/maintenances")
301	                        .contentType(MediaType.APPLICATION_JSON)
302	                        .content("""
303	                                {"requestId":"mn-1","expectedVersion":3,"readingId":"r1","anchorRevisionNo":1}
304	                                """))
305	                .andExpect(status().isCreated());
306	
307	        // 锚点时间必须严格晚于上次保养锚点：同读数/更早读数均 422
308	        mockMvc.perform(post("/api/equipment/eq-mnt/maintenances")
309	                        .contentType(MediaType.APPLICATION_JSON)
310	                        .content("""
311	                                {"requestId":"mn-2","expectedVersion":4,"readingId":"r1","anchorRevisionNo":1}
312	                                """))
313	                .andExpect(status().isUnprocessableEntity())
314	                .andExpect(jsonPath("$.code").value("ANCHOR_TIME_NOT_LATER"));
315	
316	        // 作为历史保养锚点的读数不可修订 → 409
317	        mockMvc.perform(post("/api/equipment/eq-mnt/readings/r1/revisions")
318	                        .contentType(MediaType.APPLICATION_JSON)
319	                        .content("""
320	                                {"requestId":"mn-3","expectedVersion":4,"cumulativeMinutes":120}
321	                                """))
322	                .andExpect(status().isConflict())
323	                .andExpect(jsonPath("$.code").value("READING_ANCHORED"));
324	
325	        // 非锚点读数可正常修订，随后以其新修订号完成第二次保养
326	        mockMvc.perform(post("/api/equipment/eq-mnt/readings/r2/revisions")
327	                        .contentType(MediaType.APPLICATION_JSON)
328	                        .content("""
329	                                {"requestId":"mn-4","expectedVersion":4,"cumulativeMinutes":210}
330	                                """))
331	                .andExpect(status().isCreated())
332	                .andExpect(jsonPath("$.revisionNo").value(2));
333	        mockMvc.perform(post("/api/equipment/eq-mnt/maintenances")
334	                        .contentType(MediaType.APPLICATION_JSON)
335	                        .content("""
336	                                {"requestId":"mn-5","expectedVersion":5,"readingId":"r2","anchorRevisionNo":2}
337	                                """))
338	                .andExpect(status().isCreated())
339	                .andExpect(jsonPath("$.anchorCumulativeMinutes").value(210));
340	
341	        // 保养记录保存锚点快照且不允许删除（无删除接口），历史完整
342	        mockMvc.perform(get("/api/equipment/eq-mnt/maintenances"))
343	                .andExpect(jsonPath("$", hasSize(2)))
344	                .andExpect(jsonPath("$[0].anchorCumulativeMinutes").value(100))
345	                .andExpect(jsonPath("$[1].anchorCumulativeMinutes").value(210));
346	    }
